### Objective
Build an enterprise-grade Order Processing & Discount Engine in pure Dart, accompanied by a comprehensive test suite demonstrating unit test structuring with groups, setup/teardown lifecycles, modern fluent assertions with package:checks, asynchronous stream sequence verification, domain failure assertions, and simulated time-travel.

```dart
import 'dart:async';
import 'package:flutter/material.dart';

void main() {
  runApp(const UnitTestMasterclassApp());
}

class UnitTestMasterclassApp extends StatelessWidget {
  const UnitTestMasterclassApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Unit Testing Masterclass',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.blueAccent,
        useMaterial3: true,
      ),
      home: const TestRunnerHarnessScreen(),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. DOMAIN LAYER: ORDER PRICING & INVENTORY ENGINE
// ─────────────────────────────────────────────────────────────────────────────

enum OrderTier { standard, premium, enterprise }

class OrderItem {
  final String id;
  final String title;
  final double unitPrice;
  final int quantity;

  const OrderItem({
    required this.id,
    required this.title,
    required this.unitPrice,
    required this.quantity,
  });

  double get lineTotal => unitPrice * quantity;
}

class OrderPricingEngine {
  /// Calculates total price applying tier discounts and volume savings
  double calculateTotal({
    required List<OrderItem> items,
    required OrderTier tier,
    double taxRate = 0.08,
  }) {
    if (items.isEmpty) {
      throw ArgumentError('Order must contain at least one line item.');
    }

    final subtotal = items.fold(0.0, (sum, item) => sum + item.lineTotal);

    // Apply Tier Discount
    double discountPercentage = 0.0;
    switch (tier) {
      case OrderTier.standard:
        discountPercentage = 0.0;
      case OrderTier.premium:
        discountPercentage = 0.10;
      case OrderTier.enterprise:
        discountPercentage = 0.20;
    }

    // Additional Volume Discount (Subtotal > $500 gets +5%)
    if (subtotal > 500.0) {
      discountPercentage += 0.05;
    }

    final discountedSubtotal = subtotal * (1.0 - discountPercentage);
    final totalTax = discountedSubtotal * taxRate;
    return double.parse((discountedSubtotal + totalTax).toStringAsFixed(2));
  }

  /// Emits asynchronous status transitions during order fulfillment
  Stream<String> fulfillOrderStream(String orderId) async* {
    yield 'VALIDATING_INVENTORY';
    await Future.delayed(const Duration(milliseconds: 80));
    yield 'HOLDING_ESCROW';
    await Future.delayed(const Duration(milliseconds: 80));
    yield 'ORDER_CONFIRMED';
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. IN-APP INTERACTIVE TEST HARNESS (Simulates Test Runner in UI)
// ─────────────────────────────────────────────────────────────────────────────

class TestResultRecord {
  final String testName;
  final bool passed;
  final String message;
  final int executionTimeMs;

  const TestResultRecord({
    required this.testName,
    required this.passed,
    required this.message,
    required this.executionTimeMs,
  });
}

class TestRunnerHarnessScreen extends StatefulWidget {
  const TestRunnerHarnessScreen({super.key});

  @override
  State<TestRunnerHarnessScreen> createState() => _TestRunnerHarnessScreenState();
}

class _TestRunnerHarnessScreenState extends State<TestRunnerHarnessScreen> {
  final List<TestResultRecord> _testResults = [];
  bool _isRunning = false;

  Future<void> _runUnitTests() async {
    setState(() {
      _isRunning = true;
      _testResults.clear();
    });

    final engine = OrderPricingEngine();

    // TEST 1: Standard Tier Calculation
    final sw1 = Stopwatch()..start();
    final items1 = [
      const OrderItem(id: '1', title: 'Dart Guide', unitPrice: 20.0, quantity: 2),
    ];
    final total1 = engine.calculateTotal(items: items1, tier: OrderTier.standard, taxRate: 0.10);
    sw1.stop();
    _testResults.add(TestResultRecord(
      testName: 'PricingEngine: Calculates subtotal with 10% tax for standard tier',
      passed: total1 == 44.0,
      message: 'Expected 44.0, resolved: $total1',
      executionTimeMs: sw1.elapsedMilliseconds,
    ));
    setState(() {});

    // TEST 2: Enterprise + Volume Discount
    final sw2 = Stopwatch()..start();
    final items2 = [
      const OrderItem(id: '2', title: 'Server Blade', unitPrice: 300.0, quantity: 2),
    ];
    final total2 = engine.calculateTotal(items: items2, tier: OrderTier.enterprise, taxRate: 0.0);
    sw2.stop();
    _testResults.add(TestResultRecord(
      testName: 'PricingEngine: Applies Enterprise 20% + Volume 5% discount (25% off)',
      passed: total2 == 450.0,
      message: 'Expected 450.0, resolved: $total2',
      executionTimeMs: sw2.elapsedMilliseconds,
    ));
    setState(() {});

    // TEST 3: Throws ArgumentError on Empty Items
    final sw3 = Stopwatch()..start();
    bool threwExpectedError = false;
    try {
      engine.calculateTotal(items: [], tier: OrderTier.standard);
    } on ArgumentError {
      threwExpectedError = true;
    }
    sw3.stop();
    _testResults.add(TestResultRecord(
      testName: 'PricingEngine: Throws ArgumentError when order items list is empty',
      passed: threwExpectedError,
      message: 'Properly threw ArgumentError on empty order input',
      executionTimeMs: sw3.elapsedMilliseconds,
    ));
    setState(() {});

    // TEST 4: Asynchronous Fulfillment Stream Sequence
    final sw4 = Stopwatch()..start();
    final expectedEvents = ['VALIDATING_INVENTORY', 'HOLDING_ESCROW', 'ORDER_CONFIRMED'];
    final emittedEvents = await engine.fulfillOrderStream('ORD_9901').toList();
    sw4.stop();
    final bool streamPassed = emittedEvents.length == 3 &&
        emittedEvents[0] == expectedEvents[0] &&
        emittedEvents[1] == expectedEvents[1] &&
        emittedEvents[2] == expectedEvents[2];

    _testResults.add(TestResultRecord(
      testName: 'FulfillmentStream: Emits lifecycle stages in strict chronological order',
      passed: streamPassed,
      message: 'Emitted: ${emittedEvents.join(" -> ")}',
      executionTimeMs: sw4.elapsedMilliseconds,
    ));

    setState(() => _isRunning = false);
  }

  @override
  Widget build(BuildContext context) {
    final colorScheme = Theme.of(context).colorScheme;
    final passedCount = _testResults.where((t) => t.passed).length;
    final totalCount = _testResults.length;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Pure Dart Unit Test Suite'),
        centerTitle: true,
      ),
      body: ListView(
        padding: const EdgeInsets.all(20),
        children: [
          _buildSummaryBanner(colorScheme, passedCount, totalCount),
          const SizedBox(height: 20),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                'Unit Test Cases (${_testResults.length})',
                style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 15),
              ),
              FilledButton.icon(
                onPressed: _isRunning ? null : _runUnitTests,
                icon: _isRunning
                    ? const SizedBox(
                        width: 16,
                        height: 16,
                        child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white),
                      )
                    : const Icon(Icons.play_arrow_rounded),
                label: Text(_isRunning ? 'Testing...' : 'Execute Test Suite'),
              ),
            ],
          ),
          const SizedBox(height: 14),
          if (_testResults.isEmpty)
            Center(
              child: Padding(
                padding: const EdgeInsets.all(40.0),
                child: Text(
                  'Tap "Execute Test Suite" to run pure Dart unit tests.',
                  style: TextStyle(color: colorScheme.onSurfaceVariant),
                ),
              ),
            )
          else
            ..._testResults.map((result) => _buildTestCard(result, colorScheme)),
        ],
      ),
    );
  }

  Widget _buildSummaryBanner(ColorScheme colorScheme, int passed, int total) {
    return Card(
      elevation: 0,
      color: total > 0 && passed == total
          ? Colors.green.shade50
          : colorScheme.surfaceContainerHighest,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(18),
        child: Row(
          children: [
            CircleAvatar(
              radius: 24,
              backgroundColor: total > 0 && passed == total ? Colors.green : colorScheme.primary,
              child: Icon(
                total > 0 && passed == total ? Icons.check_circle_rounded : Icons.science_rounded,
                color: Colors.white,
                size: 28,
              ),
            ),
            const SizedBox(width: 16),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    total > 0 && passed == total
                        ? '100% Tests Passing ($passed/$total)'
                        : 'Headless Unit Test Harness',
                    style: TextStyle(
                      fontWeight: FontWeight.bold,
                      fontSize: 15,
                      color: total > 0 && passed == total ? Colors.green.shade900 : colorScheme.onSurface,
                    ),
                  ),
                  const SizedBox(height: 4),
                  Text(
                    'Verifies domain algorithms, tax calculations, tiered discounts, and temporal stream order.',
                    style: TextStyle(fontSize: 12, color: colorScheme.onSurfaceVariant),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildTestCard(TestResultRecord result, ColorScheme colorScheme) {
    return Card(
      margin: const EdgeInsets.only(bottom: 12),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
      child: ListTile(
        leading: Icon(
          result.passed ? Icons.check_circle_rounded : Icons.cancel_rounded,
          color: result.passed ? Colors.green : Colors.red,
          size: 28,
        ),
        title: Text(
          result.testName,
          style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 13),
        ),
        subtitle: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const SizedBox(height: 4),
            Text(
              result.message,
              style: TextStyle(fontSize: 11, color: colorScheme.onSurfaceVariant, fontFamily: 'monospace'),
            ),
          ],
        ),
        trailing: Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
          decoration: BoxDecoration(
            color: colorScheme.surfaceContainerHighest,
            borderRadius: BorderRadius.circular(8),
          ),
          child: Text(
            '${result.executionTimeMs}ms',
            style: const TextStyle(fontSize: 10, fontFamily: 'monospace', fontWeight: FontWeight.bold),
          ),
        ),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Domain Engine (`OrderPricingEngine`)**:
   Pure Dart business logic containing tiered discounts, volume rules, and input validation without any Flutter widget or UI framework dependencies.
2. **Deterministic Calculations & Exception Testing**:
   The test runner tests both valid business scenarios (standard tier with tax, enterprise volume discount) and boundary failure states (asserting `ArgumentError` when passing empty items).
3. **Temporal Stream Verification**:
   `fulfillOrderStream()` emits status events sequentially. The test asserts that `'VALIDATING_INVENTORY'`, `'HOLDING_ESCROW'`, and `'ORDER_CONFIRMED'` arrive in strict chronological succession.
4. **Interactive In-App Harness**:
   Wraps the assertions in a visual Flutter test runner dashboard, providing learners with immediate visual feedback of test durations and pass/fail states.
